package com.swimflow.service;
import com.swimflow.api.Requests;import com.swimflow.model.*;import com.swimflow.repo.*;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;import org.springframework.http.HttpStatus;import java.time.*;import java.util.*;
@Service public class SessionService {
 private final SessionRepository sessions;private final EnrollmentRepository enrollments;private final ItemService items;
 public SessionService(SessionRepository sessions,EnrollmentRepository enrollments,ItemService items){this.sessions=sessions;this.enrollments=enrollments;this.items=items;}
 public List<SwimSession> list(){return sessions.findAll();}
 public SwimSession get(Long id){return sessions.findById(id).orElseThrow(()->new BusinessException(HttpStatus.NOT_FOUND,"Sessão não encontrada"));}
 @Transactional public SwimSession create(Requests.Session r){SwimItem item=items.get(r.workoutId());if(item.type!=ItemType.WORKOUT)throw new BusinessException(HttpStatus.BAD_REQUEST,"Sessão requer WORKOUT");if(!items.available(item.id))throw new BusinessException(HttpStatus.CONFLICT,"Treino indisponível");if(!r.startsAt().isAfter(LocalDateTime.now()))throw new BusinessException(HttpStatus.BAD_REQUEST,"Data deve ser futura");return sessions.save(new SwimSession(item,r.instructor(),r.startsAt(),r.capacity()));}
 @Transactional public Enrollment enroll(Long sessionId,String email){SwimSession session=sessions.lockById(sessionId).orElseThrow(()->new BusinessException(HttpStatus.NOT_FOUND,"Sessão não encontrada"));if(session.status!=SessionStatus.ABERTA||!session.startsAt.isAfter(LocalDateTime.now()))throw new BusinessException(HttpStatus.CONFLICT,"Sessão fechada");if(!items.available(session.workout.id))throw new BusinessException(HttpStatus.CONFLICT,"Treino indisponível");String normalized=email.trim().toLowerCase(Locale.ROOT);Optional<Enrollment> existing=enrollments.findBySessionIdAndSwimmerEmail(sessionId,normalized);if(existing.isPresent() && existing.get().status==EnrollmentStatus.CONFIRMADA)return existing.get();if(enrollments.countBySessionIdAndStatus(sessionId,EnrollmentStatus.CONFIRMADA)>=session.capacity)throw new BusinessException(HttpStatus.CONFLICT,"Sem vagas disponíveis");Enrollment enrollment=existing.orElseGet(()->new Enrollment(session,normalized));enrollment.status=EnrollmentStatus.CONFIRMADA;return enrollments.save(enrollment);}
 @Transactional public void cancel(Long sessionId,Long enrollmentId){sessions.lockById(sessionId).orElseThrow(()->new BusinessException(HttpStatus.NOT_FOUND,"Sessão não encontrada"));Enrollment enrollment=enrollments.findById(enrollmentId).orElseThrow(()->new BusinessException(HttpStatus.NOT_FOUND,"Inscrição não encontrada"));if(!enrollment.session.id.equals(sessionId))throw new BusinessException(HttpStatus.NOT_FOUND,"Inscrição não pertence à sessão");enrollment.status=EnrollmentStatus.CANCELADA;enrollments.save(enrollment);}
}
